#include "nvt_protocol.h"
#include <assert.h>
#include <stdio.h>
#include <string.h>

static const uint8_t fw_wire[18] = {
    0xa5,0x5a, 0x10,0xef,0x12,0x20,0x04,0x38,0x09,0x60,0,0,0,0,0,1,0,0
};
/* Golden wire bytes, not generated by the candidate: ID7 DOWN at1080,2400;
 * ID3 MOVE at7,9. Pressure extensions follow record order, not IDs. */
static const uint8_t two_contacts[67] = {
    [0]=0xa5,[1]=0x5a,
    [2]=0x39,[3]=0x43,[4]=0x96,[5]=0x80,[6]=0,[7]=0,
    [8]=0x1a,[9]=0,[10]=0,[11]=0x79,[12]=5,[13]=5,
    [64]=4,[65]=2,[66]=0xe1
};

static void init(struct nvt_state *s)
{
    struct nvt_fw_info f;
    assert(nvt_decode_fwinfo(fw_wire, sizeof(fw_wire), &f) == NVT_OK);
    assert(nvt_state_init(s, &f) == NVT_OK);
}

static void unchanged_error(struct nvt_state *s, const uint8_t *rx, size_t n, int expected)
{
    struct nvt_state before;
    struct nvt_frame out, saved;
    memcpy(&before, s, sizeof(before));
    memset(&out, 0xa5, sizeof(out)); memcpy(&saved, &out, sizeof(out));
    assert(nvt_decode_points(s, rx, n, &out) == expected);
    assert(memcmp(s, &before, sizeof(before)) == 0);
    assert(memcmp(&out, &saved, sizeof(out)) == 0);
}

static void requests(void)
{
    static const unsigned address[] = {0x22d78,0x22d60,0x22d9a,0x22d00};
    static const unsigned wire[] = {18,7,4,67};
    static const uint8_t command[] = {0x78,0x60,0x1a,0};
    struct nvt_request r, saved;
    for (unsigned kind=0; kind<4; ++kind) {
        memset(&r,0xcc,sizeof(r));
        assert(nvt_make_request((enum nvt_read_kind)kind,&r)==NVT_OK);
        assert(r.address==address[kind] && r.wire_length==wire[kind]);
        assert(r.payload_length+2==wire[kind] && r.tx[0]==command[kind]);
        assert(r.page[0]==0xff && r.page[1]==4 && r.page[2]==(kind==2?0x5b:0x5a));
        assert(r.restore_page[0]==0xff && r.restore_page[1]==4 && r.restore_page[2]==0x5a);
        for (unsigned j=1;j<NVT_MAX_WIRE;++j) assert(r.tx[j]==0);
    }
    memcpy(&saved,&r,sizeof(r));
    assert(nvt_make_request((enum nvt_read_kind)99,&r)==NVT_ERR_ARGUMENT);
    assert(memcmp(&r,&saved,sizeof(r))==0);
    assert(nvt_make_request(NVT_READ_FWINFO,NULL)==NVT_ERR_ARGUMENT);
    const uint8_t chip[]={0x0c,0,0,0x72,0x66,3}, other[]={0x0b,0,0,0x72,0x66,3};
    assert(nvt_check_observed_chip(chip,6)==NVT_OK);
    assert(nvt_check_observed_chip(other,6)==NVT_ERR_IDENTITY);
    assert(nvt_check_observed_chip(chip,5)==NVT_ERR_LENGTH);
}

static void replies(void)
{
    uint8_t b[70]={0}; struct nvt_fw_info f, saved;
    assert(nvt_decode_fwinfo(fw_wire,18,&f)==NVT_OK);
    assert(f.version==16 && f.x_channels==18 && f.y_channels==32);
    assert(f.max_x==1080 && f.max_y==2400 && f.firmware_type==1 && f.buttons==0);
    memcpy(&saved,&f,sizeof(f));
    for(size_t n=0;n<70;++n) if(n!=18) {
        assert(nvt_decode_fwinfo(b,n,&f)==NVT_ERR_LENGTH);
        assert(memcmp(&f,&saved,sizeof(f))==0);
    }
    memcpy(b,fw_wire,18); b[3]^=1;
    assert(nvt_decode_fwinfo(b,18,&f)==NVT_ERR_FW_CHECKSUM);
    assert(memcmp(&f,&saved,sizeof(f))==0);
    memcpy(b,fw_wire,18); b[4]=0;
    assert(nvt_decode_fwinfo(b,18,&f)==NVT_ERR_GEOMETRY);
    memcpy(b,fw_wire,18); b[6]=4;b[7]=0x39;
    assert(nvt_decode_fwinfo(b,18,&f)==NVT_ERR_GEOMETRY);
    memcpy(b,fw_wire,18); b[8]=9;b[9]=0x61;
    assert(nvt_decode_fwinfo(b,18,&f)==NVT_ERR_GEOMETRY);
    memcpy(b,fw_wire,18); b[6]=0;b[7]=0;
    assert(nvt_decode_fwinfo(b,18,&f)==NVT_ERR_GEOMETRY);
    /* Smaller firmware geometry is used, not replaced with hardcoded panel size. */
    memcpy(b,fw_wire,18); b[6]=2;b[7]=0xd0;b[8]=5;b[9]=0;
    assert(nvt_decode_fwinfo(b,18,&f)==NVT_OK && f.max_x==720 && f.max_y==1280);
    struct nvt_state s; assert(nvt_state_init(&s,&f)==NVT_OK);
    unchanged_error(&s,two_contacts,67,NVT_ERR_COORDINATE);
    struct nvt_reset_info reset;
    const uint8_t rst[]={0x99,0x88,0xa3,1,2,3,4};
    assert(nvt_decode_reset(rst,7,&reset)==NVT_OK);
    assert(reset.state==0xa3 && reset.detail[3]==4 && nvt_reset_ready(&reset,0xa3));
    reset.state=0xa0;assert(nvt_reset_ready(&reset,0xa0) && !nvt_reset_ready(&reset,0xa1));
    reset.state=0xaf;assert(nvt_reset_ready(&reset,0xa3));
    reset.state=0xb0;assert(!nvt_reset_ready(&reset,0xa0));
    reset.state=0x9f;assert(!nvt_reset_ready(&reset,0xa0));
    assert(!nvt_reset_ready(&reset,0x9f) && !nvt_reset_ready(NULL,0xa0));
    assert(nvt_decode_reset(rst,6,&reset)==NVT_ERR_LENGTH);
    uint16_t pid=0;const uint8_t pidwire[]={0x12,0x34,0x37,0x59};
    assert(nvt_decode_pid(pidwire,4,&pid)==NVT_OK && pid==0x5937);
    assert(nvt_decode_pid(pidwire,3,&pid)==NVT_ERR_LENGTH && pid==0x5937);
}

static void contacts(void)
{
    struct nvt_state s;struct nvt_frame f;init(&s);
    assert(nvt_decode_points(&s,two_contacts,67,&f)==NVT_OK);
    assert(f.kind==NVT_PACKET_CONTACTS && f.active_count==2 && f.event_count==2);
    assert(f.events[0].id==3 && f.events[0].kind==NVT_DOWN);
    assert(f.events[0].contact.wire_status==2 && f.events[0].contact.x==7 && f.events[0].contact.y==9);
    assert(f.events[0].contact.pressure==517 && f.events[0].contact.width==5);
    assert(f.events[1].id==7 && f.events[1].kind==NVT_DOWN);
    assert(f.events[1].contact.x==1080 && f.events[1].contact.y==2400);
    assert(f.events[1].contact.pressure==1000 && f.events[1].contact.width==1);
    assert(f.native_tail[4]==0xe1);
    uint8_t b[67]={0};b[2]=0x1a;b[5]=0x79; /* ID3 present, ID7 absent. */
    assert(nvt_decode_points(&s,b,67,&f)==NVT_OK && f.active_count==1 && f.event_count==2);
    assert(f.events[0].kind==NVT_MOVE && f.events[0].contact.pressure==1);
    assert(f.events[1].id==7 && f.events[1].kind==NVT_UP && !f.events[1].contact.active);
    assert(f.events[1].contact.x==1080 && f.events[1].contact.pressure==0);
    /* Explicit non-active status releases based on last position; stale x/y are ignored. */
    b[2]=0x1b;b[3]=b[4]=b[5]=0xff;
    assert(nvt_decode_points(&s,b,67,&f)==NVT_OK && f.event_count==1 && f.active_count==0);
    assert(f.events[0].kind==NVT_UP && f.events[0].contact.x==7 && f.events[0].contact.wire_status==3);
    memset(b,0xff,sizeof(b));
    assert(nvt_decode_points(&s,b,67,&f)==NVT_OK && f.event_count==0);
    /* A native all-ff unused packet is not a checksum failure. No checksum is invented. */
    for(unsigned tail=0;tail<256;++tail) {
        b[66]=(uint8_t)tail;
        assert(nvt_decode_points(&s,b,67,&f)==NVT_OK && f.event_count==0);
        assert(f.native_tail[4]==tail);
    }
}

static void malformed(void)
{
    struct nvt_state s;struct nvt_frame f;init(&s);
    assert(nvt_decode_points(&s,two_contacts,67,&f)==NVT_OK);
    uint8_t b[72];memcpy(b,two_contacts,67);
    for(size_t n=0;n<72;++n) if(n!=67) unchanged_error(&s,b,n,NVT_ERR_LENGTH);
    unchanged_error(&s,NULL,67,NVT_ERR_ARGUMENT);
    b[2]=1;unchanged_error(&s,b,67,NVT_ERR_CONTACT_ID); /* ID0 active */
    b[2]=0x59;unchanged_error(&s,b,67,NVT_ERR_CONTACT_ID); /* ID11 active */
    memcpy(b,two_contacts,67);b[5]=0x90;
    unchanged_error(&s,b,67,NVT_ERR_COORDINATE); /* x1081 */
    memcpy(b,two_contacts,67);b[5]=0x81;
    unchanged_error(&s,b,67,NVT_ERR_COORDINATE); /* y2401 */
    memcpy(b,two_contacts,67);b[8]=0x3a;
    unchanged_error(&s,b,67,NVT_ERR_DUPLICATE_ID);
    b[8]=0x3b;unchanged_error(&s,b,67,NVT_ERR_DUPLICATE_ID);
    assert(nvt_cancel_contacts(&s,&f)==NVT_OK && f.event_count==2 && f.active_count==0);
    for(unsigned i=0;i<f.event_count;++i) assert(f.events[i].kind==NVT_UP);
    assert(nvt_cancel_contacts(&s,&f)==NVT_OK && f.event_count==0);
}

static void recovery_packets(void)
{
    struct nvt_state s;struct nvt_frame f;uint8_t b[67]={0};init(&s);
    assert(nvt_decode_points(&s,two_contacts,67,&f)==NVT_OK);
    for(unsigned i=0;i<6;++i)b[i+2]=(i&1)?0xfe:0xfd;
    for(unsigned i=1;i<=11;++i) {
        assert(nvt_decode_points(&s,b,67,&f)==NVT_OK && f.kind==NVT_PACKET_WDT);
        assert(f.wdt_streak==i && f.recovery_required==(i==11));
        assert(f.event_count==0 && f.active_count==2 && s.contacts[6].active);
    }
    assert(s.wdt_streak==0); /* Native recovery counter resets after threshold. */
    assert(nvt_decode_points(&s,b,67,&f)==NVT_OK && f.wdt_streak==1);
    memset(b+2,0x77,6);
    assert(nvt_decode_points(&s,b,67,&f)==NVT_OK && f.kind==NVT_PACKET_ESD);
    assert(f.event_count==0 && s.wdt_streak==0 && s.contacts[6].active);
    assert(nvt_cancel_contacts(&s,&f)==NVT_OK && f.event_count==2);
}

static void maximum_and_mutations(void)
{
    struct nvt_state s;struct nvt_frame f;uint8_t b[67]={0};init(&s);
    for(unsigned i=0;i<10;++i)b[2+6*i]=(uint8_t)(((10-i)<<3)|1);
    assert(nvt_decode_points(&s,b,67,&f)==NVT_OK && f.event_count==10 && f.active_count==10);
    for(unsigned i=0;i<10;++i)assert(f.events[i].id==i+1 && f.events[i].kind==NVT_DOWN);
    assert(nvt_cancel_contacts(&s,&f)==NVT_OK && f.event_count==10);
    /* Bounded deterministic malformed-input exercise. Sanitizers also check all accesses. */
    uint32_t random=0x12345678;
    for(unsigned trial=0;trial<10000;++trial) {
        for(unsigned j=0;j<sizeof(b);++j) {
            random^=random<<13;random^=random>>17;random^=random<<5;b[j]=(uint8_t)random;
        }
        struct nvt_state before;struct nvt_frame old;
        memcpy(&before,&s,sizeof(s));memset(&f,0x5a,sizeof(f));memcpy(&old,&f,sizeof(f));
        int result=nvt_decode_points(&s,b,sizeof(b),&f);
        if(result!=NVT_OK) {
            assert(memcmp(&s,&before,sizeof(s))==0 && memcmp(&f,&old,sizeof(f))==0);
        } else {
            assert(f.event_count<=10 && f.active_count<=10);
            for(unsigned i=0;i<10;++i)if(s.contacts[i].active)
                assert(s.contacts[i].x<=s.max_x && s.contacts[i].y<=s.max_y);
        }
    }
}

int main(void)
{
    requests();replies();contacts();malformed();recovery_packets();maximum_and_mutations();
    puts("PASS: NVT raw-wire/FW integrity/geometry/contact lifecycle/recovery/10000 mutations");
    return 0;
}
